  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello प्रतीक आपकी Hawkins कंटूरा Black दो लीटर pressure cooker की request IndiaMART पर placed है बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "चलिए अब body material के बारे में बात कर लेते हैं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए aluminium या कुछ और?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "तीनों ही चाहिए मुझे steel और non-steel।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "आप लोग जैसे कि मुझे ना कि इसमें डेढ़ लीटर दो लीटर तीन लीटर पाँच लीटर और साढ़े छह लीटर इन सबके ही model चाहिए और मुझे जो MRP पे less चाहिए वो चाहिए 50%"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "जी आपकी ये सारी details note कर ली गई हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "जल्द ही एक seller आपसे contact करेंगे।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
